</section></main><style>.violation-picker{position:relative}.violation-picker>select{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important}.violation-picker-button{width:100%;min-height:48px;padding:10px 14px;border:1px solid #cfd6e4;border-radius:10px;background:#fff;display:flex;align-items:center;justify-content:space-between;gap:12px;text-align:left;font:inherit;color:#1f2937;cursor:pointer}.violation-picker-button:focus{outline:0;box-shadow:0 0 0 3px rgba(13,110,253,.14);border-color:#86b7fe}.violation-picker-button i{font-size:.9rem;color:#64748b;transition:transform .15s}.violation-picker.is-open .violation-picker-button i{transform:rotate(180deg)}.violation-picker-menu{position:absolute;z-index:1055;left:0;right:0;top:calc(100% + 6px);max-height:330px;overflow:auto;background:#fff;border:1px solid #d7deea;border-radius:10px;box-shadow:0 12px 28px rgba(15,23,42,.14);padding:6px}.violation-picker-option{width:100%;border:0;background:#fff;padding:10px 12px;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;border-radius:8px;text-align:left;font:inherit;cursor:pointer}.violation-picker-option:hover,.violation-picker-option:focus{background:#f4f7fb;outline:0}.violation-picker-option.is-selected{background:#eef5ff}.violation-name{flex:1;min-width:0;line-height:1.35}.violation-points{flex:0 0 auto;white-space:nowrap;color:#b42318;font-weight:800}.violation-picker-label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.violation-picker-label.has-value{font-weight:600}.violation-picker-label .selected-points{margin-left:8px;color:#b42318;font-weight:800}.violation-picker + #poinPreview{display:none}</style><script>(()=>{const root=document.querySelector('[data-violation-picker]');if(!root)return;const select=root.querySelector('#jenisPelanggaranSelect'),button=root.querySelector('.violation-picker-button'),label=root.querySelector('.violation-picker-label'),menu=root.querySelector('.violation-picker-menu'),options=[...root.querySelectorAll('.violation-picker-option')],preview=document.getElementById('poinPreview');const setValue=(value,close=true)=>{select.value=value||'';const opt=select.options[select.selectedIndex],poin=opt?.dataset?.poin||'';label.textContent=value?(opt?.textContent?.trim()||'- Pilih jenis pelanggaran -'):'- Pilih jenis pelanggaran -';label.classList.toggle('has-value',!!value);options.forEach(x=>x.classList.toggle('is-selected',x.dataset.value===String(value)));preview.textContent=poin?('Poin transaksi: +'+poin):'';select.dispatchEvent(new Event('change',{bubbles:true}));if(close){menu.hidden=true;root.classList.remove('is-open');button.setAttribute('aria-expanded','false')}};button.addEventListener('click',()=>{menu.hidden=!menu.hidden;root.classList.toggle('is-open',!menu.hidden);button.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden){const selected=options.find(x=>x.dataset.value===select.value);selected?.scrollIntoView({block:'nearest'})}});options.forEach(opt=>opt.addEventListener('click',()=>setValue(opt.dataset.value)));document.addEventListener('click',e=>{if(!root.contains(e.target)){menu.hidden=true;root.classList.remove('is-open');button.setAttribute('aria-expanded','false')}});button.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();button.click()}if(e.key==='Escape'){menu.hidden=true;root.classList.remove('is-open');button.setAttribute('aria-expanded','false')}});setValue(select.value,false)})();</script><?php require_once __DIR__.'/../layouts/footer.php'; ?>
